DROP FUNCTION IF EXISTS `get_ap_paid`$$
CREATE FUNCTION `get_ap_paid`(V_type VARCHAR(200),V_invno VARCHAR(200),v_dateto VARCHAR(200)) RETURNS double
    DETERMINISTIC
BEGIN
       DECLARE s_qty DOUBLE;

        IF V_type<>'RECEIPTS' THEN 

          IF V_type='INVOICE' THEN
           SELECT  SUM(amountpaid) INTO s_qty FROM (
           SELECT sum(b.amountpaid) AS amountpaid from  ap_prepayment a,ap_prepayment_details b where a.pno=b.rno and  invno=V_invno and pdate<=v_dateto AND posted=1
            union all
           select sum(abs(b.amountpaid)) AS amountpaid from ap_allocations a,ap_allocations_details b where a.rno=b.rno and remarks='INVOICE' AND INVNO=V_invno AND rdate<=v_dateto  AND posted=1 
           ) AS A;
          END IF;

          IF V_type='CREDITNOTE' THEN
           SELECT  SUM(amountpaid) INTO s_qty FROM (           
           select sum(abs(b.amountpaid)) AS amountpaid from ap_allocations a,ap_allocations_details b where a.rno=b.rno and remarks='CREDIT' AND INVNO=V_invno AND rdate<=v_dateto  AND posted=1 
           ) AS A;
          END IF;

        END IF;

       IF V_type='RECEIPTS' THEN 
         SELECT  SUM(amountpaid) INTO s_qty FROM (
         SELECT sum(b.amountpaid) AS amountpaid from  ap_prepayment a,ap_prepayment_details b where a.pno=b.rno and  a.pno=V_invno and pdate<=v_dateto AND posted=1
          union all
         select sum(abs(b.amountpaid)) AS amountpaid from ap_allocations a,ap_allocations_details b where a.rno=b.rno and remarks='RECEIPT' AND INVNO=V_invno AND rdate<=v_dateto  AND posted=1 
          ) AS A;
        END IF;

        IF (s_qty < 0 or s_qty  IS NULL) THEN SET s_qty=0;
        END IF;
        RETURN s_qty;
  END$$

