DROP FUNCTION IF EXISTS `get_average_cost`$$
CREATE FUNCTION `get_average_cost`(v_no VARCHAR(200)) RETURNS double
    DETERMINISTIC
BEGIN
       DECLARE bname  DOUBLE;
         
       SELECT ifnull(SUM(if(type='INPUT',qty*uprice,0))/SUM(if(type='OUTPUT',qty*weight,0)),0) INTO bname  FROM ass_d where no=v_no ;
         
     
        RETURN bname;
 END$$

-- ------------------------------------------------------------
DROP FUNCTION IF EXISTS `get_average_cost_p`$$
CREATE FUNCTION `get_average_cost_p`(v_no VARCHAR(200)) RETURNS double
    DETERMINISTIC
BEGIN
       DECLARE bname  DOUBLE;
         
       SELECT ifnull(SUM(if(type<>'OUTPUT',qty*uprice,0))/SUM(if(type='OUTPUT',qty*weight,0)),0) INTO bname  FROM Packing_d where no=v_no  group by no limit 1 ;
         
     
        RETURN bname;
 END$$

-- ------------------------------------------------------------
DROP FUNCTION IF EXISTS `get_average_cost_p_id`$$
CREATE FUNCTION `get_average_cost_p_id`(v_no VARCHAR(200),id_no VARCHAR(200),has_bom VARCHAR(200)) RETURNS double
    DETERMINISTIC
BEGIN
       DECLARE bname  DOUBLE;
         
         
		  IF  has_bom='1' THEN
          SELECT ifnull(SUM(if(type<>'OUTPUT' and unique_id=id_no,qty*uprice,0))/SUM(if(type='OUTPUT'  and adid=id_no,qty*weight,0)),0) INTO bname  FROM Packing_d where no=v_no group by no limit 1 ;
       
          ELSE
          SELECT ifnull(SUM(if(type<>'OUTPUT' and unique_id=id_no,qty*uprice,0))/SUM(if(type='OUTPUT'  and adid=id_no,qty*weight,0)),0) INTO bname  FROM Packing_d where no=v_no  group by no limit 1;
       
          END IF;
     
        RETURN bname;
 END$$

