DROP FUNCTION IF EXISTS `get_batch_exp`$$
CREATE FUNCTION `get_batch_exp`(v_code  VARCHAR(200),v_batchno  VARCHAR(200)) RETURNS varchar(200) CHARSET latin1
    DETERMINISTIC
BEGIN
       DECLARE bname VARCHAR(200);
          
          SELECT if(expirydate='2050-01-01','',expirydate) INTO bname  FROM stran where code=v_code and batchno=v_batchno and ts='+' limit 1;
          
         IF (bname =''  or bname  IS NULL) THEN SET bname='2050-01-01';
         END IF;
        RETURN ifnull(bname,'2050-01-01');
 END$$

