DROP FUNCTION IF EXISTS `get_budget`$$
CREATE FUNCTION `get_budget`(V_year VARCHAR(300),V_month VARCHAR(300),V_code VARCHAR(300),V_costcenter VARCHAR(300),V_branch VARCHAR(300)) RETURNS double
    DETERMINISTIC
BEGIN
       DECLARE s_qty DOUBLE;
           
         SELECT sum(amount/rate)  INTO s_qty FROM  jt where trantype='Budget' and  period=V_year and bmonth=V_month  and code=v_code  and costcenter like if(V_costcenter='ALL','%%',V_costcenter) and profitc like if(V_branch='ALL','%%',V_branch);
     

        IF (s_qty IS NULL) THEN SET s_qty=0;
        END IF;
        RETURN s_qty;
  END$$

-- ------------------------------------------------------------
DROP FUNCTION IF EXISTS `get_budget_todate`$$
CREATE FUNCTION `get_budget_todate`(V_year VARCHAR(300),V_month VARCHAR(300),V_code VARCHAR(300),V_costcenter VARCHAR(300),V_branch  VARCHAR(300)) RETURNS double
    DETERMINISTIC
BEGIN
       DECLARE s_qty DOUBLE;

 
         SELECT sum(amount/rate)  INTO s_qty FROM  jt where trantype='Budget' and  period=V_year and bmonth<=V_month  and code=v_code   and costcenter like if(V_costcenter='ALL','%%',V_costcenter) and profitc like if(V_branch='ALL','%%',V_branch)  group by code;

        IF (s_qty IS NULL) THEN SET s_qty=0;
        END IF;
        RETURN s_qty;
  END$$

