DROP FUNCTION IF EXISTS `get_category`$$
CREATE FUNCTION `get_category`(v_code VARCHAR(200),v_type  VARCHAR(200) ) RETURNS varchar(80) CHARSET latin1
    DETERMINISTIC
BEGIN
       DECLARE bname VARCHAR(80);
          IF  v_type='stocks' THEN
          SELECT categ INTO bname  FROM si where code=v_code group by code limit 1;
          ELSE
          SELECT category INTO bname  FROM accounts where code=v_code group by code limit 1;
          END IF;
     
        RETURN ifnull(bname,'');
 END$$

