-- ------------------------------------------------------------
DROP FUNCTION IF EXISTS `get_cost_recipe`$$
CREATE FUNCTION `get_cost_recipe`(v_code VARCHAR(200)) RETURNS double
    DETERMINISTIC
BEGIN
       DECLARE bname DOUBLE;
         
           SELECT cost  INTO bname  from (
           SELECT a.code,a.descr,sum(b.cost) as cost from si a,assembly_d b where recipe<>'' and a.recipe=b.no group by code,b.no
           union  SELECT a.code,a.descr,sum(a.cost) as cost from si a where recipe=''  group by code ) as  a where code=v_code;
     
        RETURN ifnull(bname,0);
 END$$

-- ------------------------------------------------------------
DROP FUNCTION IF EXISTS `get_CSN`$$
CREATE FUNCTION `get_CSN`(v_aircraft VARCHAR(200)) RETURNS int(11)
    DETERMINISTIC
BEGIN
       DECLARE bname DOUBLE;
       DECLARE b_name DOUBLE;
       DECLARE D_DATE date;       
       DECLARE AIRCRAFT_CSN DOUBLE;
          
          select ddate INTO D_DATE from aircraft where ainfo=v_aircraft;

          select ifnull(totalflightcycles,0) INTO AIRCRAFT_CSN from aircraft where ainfo=v_aircraft;

          select ifnull(SUM(totalcycle),0) INTO bname from flight_log_post where posted=1 and ldate>=D_DATE and  flightreg=v_aircraft;
          
          SET b_name=bname+AIRCRAFT_CSN;
         
     
        RETURN IFNULL(b_name,0);
 END$$

-- ------------------------------------------------------------
DROP FUNCTION IF EXISTS `get_CSN_PERIOD`$$
CREATE FUNCTION `get_CSN_PERIOD`(v_aircraft VARCHAR(200),v_period VARCHAR(200)) RETURNS int(11)
    DETERMINISTIC
BEGIN
       DECLARE bname DOUBLE;
          
          select SUM(totalairtime) INTO bname from flight_log_post where orderno<>'' and ldate between   date_add(date(now()), interval -v_period  day) and date(now()) and flightreg=v_aircraft;
     
        RETURN IFNULL(bname,0);
 END$$

