DROP FUNCTION IF EXISTS `get_currency_factor`$$
CREATE FUNCTION `get_currency_factor`(V_currency VARCHAR(200) ,V_period VARCHAR(200)) RETURNS double
    DETERMINISTIC
BEGIN
       DECLARE s_qty DOUBLE;

          SELECT IFNULL(amount,1) INTO s_qty FROM exchangerates WHERE code=V_currency AND period=V_period LIMIT 1;

          IF (s_qty < 0 or s_qty  IS NULL) THEN SET s_qty=1;

          END IF;

        RETURN s_qty;
 END$$

-- ------------------------------------------------------------
DROP FUNCTION IF EXISTS `get_customer_branch`$$
CREATE FUNCTION `get_customer_branch`(v_code VARCHAR(200)) RETURNS varchar(200) CHARSET latin1
    DETERMINISTIC
BEGIN
       DECLARE s_cogs VARCHAR(200);

       SELECT ifnull(profitc,'') INTO s_cogs from invoices where clientcode =v_code LIMIT 1 ;

          if (s_cogs='' or isnull(s_cogs)) then
          SELECT ifnull(profitc,'') INTO s_cogs from orders where clientcode =v_code LIMIT 1;
          END IF;

          if (s_cogs='' or isnull(s_cogs)) then
          SELECT ifnull(profitc,'') INTO s_cogs from ar_prepayment where ccode =v_code LIMIT 1;
          END IF;
          RETURN s_cogs;
 END$$

