-- ------------------------------------------------------------
DROP FUNCTION IF EXISTS `get_flightlog`$$
CREATE FUNCTION `get_flightlog`(V_year VARCHAR(200),V_month VARCHAR(200),V_costcenter VARCHAR(200),v_noncommerical varchar(5)) RETURNS double
    DETERMINISTIC
BEGIN
       DECLARE s_qty DOUBLE;

        IF V_costcenter='ALL' THEN 
           
         SELECT sum(flt_time)  INTO s_qty FROM  flightmanifest a, flightmanifest_d b where a.orderno=b.orderno and posted=1 and month(tdate)=V_month and year(tdate)=V_year and ccommercial=v_noncommerical ;

        END IF;

        IF V_costcenter<>'ALL' THEN 
           
         SELECT sum(flt_time)  INTO s_qty FROM  flightmanifest a, flightmanifest_d b where a.orderno=b.orderno and posted=1 and month(tdate)=V_month and year(tdate)=V_year and flightreg=V_costcenter and ccommercial=v_noncommerical group by flightreg;

        END IF;



        IF (s_qty < 0 or s_qty  IS NULL) THEN SET s_qty=0;
        END IF;
        RETURN s_qty;
  END$$

-- ------------------------------------------------------------
DROP FUNCTION IF EXISTS `get_flightlog_todate`$$
CREATE FUNCTION `get_flightlog_todate`(V_year VARCHAR(200),V_month VARCHAR(200),V_costcenter VARCHAR(200),v_noncommerical varchar(5)) RETURNS double
    DETERMINISTIC
BEGIN
       DECLARE s_qty DOUBLE;

        IF V_costcenter='ALL' THEN 
           
         SELECT sum(flt_time)  INTO s_qty FROM  flightmanifest a, flightmanifest_d b where a.orderno=b.orderno and posted=1 and month(tdate)<=V_month and year(tdate)=V_year and ccommercial=v_noncommerical ;

        END IF;

        IF V_costcenter<>'ALL' THEN 
           
         SELECT sum(flt_time)  INTO s_qty FROM  flightmanifest a, flightmanifest_d b where a.orderno=b.orderno and posted=1 and month(tdate)<=V_month and year(tdate)=V_year and flightreg=V_costcenter and ccommercial=v_noncommerical group by flightreg;

        END IF;


        IF (s_qty < 0 or s_qty  IS NULL) THEN SET s_qty=0;
        END IF;
        RETURN s_qty;
  END$$

