DROP FUNCTION IF EXISTS `get_hrs_budget`$$
CREATE FUNCTION `get_hrs_budget`(V_year VARCHAR(200),V_month VARCHAR(200),V_code VARCHAR(200),V_costcenter VARCHAR(200),V_type VARCHAR(200)) RETURNS double
    DETERMINISTIC
BEGIN
       DECLARE s_qty DOUBLE;

        IF V_costcenter='ALL' THEN 

          IF V_type='FUEL' THEN
            SELECT sum(fuel)  INTO s_qty FROM  jt_fuel where trantype='Budget' and  period=V_year and bmonth=V_month group by costcenter;
           END IF;
            IF V_type<>'FUEL' THEN 
            SELECT sum(amount) INTO s_qty FROM  jt_fuel where trantype='Budget' and  period=V_year and bmonth=V_month and code=v_code group by code;
          
          END IF;      
         
        END IF;

        IF V_costcenter<>'ALL' THEN 

           IF V_type='FUEL' THEN
            SELECT sum(fuel)  INTO s_qty FROM  jt_fuel where trantype='Budget' and  period=V_year and bmonth=V_month  and costcenter=V_costcenter group by costcenter;
           END IF;
           IF V_type<>'FUEL' THEN 
            SELECT sum(amount)  INTO s_qty FROM  jt_fuel where trantype='Budget' and  period=V_year and bmonth=V_month  and code=v_code and costcenter=V_costcenter limit 1;
          
          END IF;   
         
        END IF;


        IF (s_qty < 0 or s_qty  IS NULL) THEN SET s_qty=0;
        END IF;
        RETURN s_qty;
  END$$

-- ------------------------------------------------------------
DROP FUNCTION IF EXISTS `get_hrs_budget_todate`$$
CREATE FUNCTION `get_hrs_budget_todate`(V_year VARCHAR(200),V_month VARCHAR(200),V_code VARCHAR(200),V_costcenter VARCHAR(200),V_type VARCHAR(200)) RETURNS double
    DETERMINISTIC
BEGIN
       DECLARE s_qty DOUBLE;

       IF V_costcenter='ALL' THEN 

          IF V_type='FUEL' THEN
            SELECT sum(fuel)  INTO s_qty FROM  jt_fuel where trantype='Budget' and  period=V_year and bmonth<=V_month group by costcenter;
          END IF;

           IF V_type<>'FUEL' THEN 
            SELECT sum(amount)  INTO s_qty FROM  jt_fuel where trantype='Budget' and  period=V_year and bmonth<=V_month and code=v_code group by code;
          
          END IF;      
         
        END IF;

        IF V_costcenter<>'ALL' THEN 

           IF V_type='FUEL' THEN 
             SELECT sum(fuel)  INTO s_qty FROM  jt_fuel where trantype='Budget' and  period=V_year and bmonth<=V_month  and costcenter=V_costcenter group by costcenter;
           END IF;
           IF V_type<>'FUEL' THEN 
            SELECT sum(amount)  INTO s_qty FROM  jt_fuel where trantype='Budget' and  period=V_year and bmonth<=V_month  and code=v_code and costcenter=V_costcenter limit 1;
          
          END IF;   
         
        END IF;


        IF (s_qty < 0 or s_qty  IS NULL) THEN SET s_qty=0;
        END IF;
        RETURN s_qty;
  END$$

