DROP FUNCTION IF EXISTS `get_kms`$$
CREATE FUNCTION `get_kms`(v_vehicle VARCHAR(200)) RETURNS double
    DETERMINISTIC
BEGIN
       DECLARE bname DOUBLE;
       DECLARE b_name DOUBLE;
       DECLARE D_DATE date;
       DECLARE vehicle_km DOUBLE;      
          
          select pmileageasat INTO D_DATE from vehicles where vid=v_vehicle;

          select ifnull(pmileage,0) INTO vehicle_km from vehicles where vid=v_vehicle;         

          select ifnull(SUM(totalkms),0) INTO bname from journeylog where posted=1 and journeydate>=D_DATE and  vehicle=v_vehicle;
          
          SET b_name=bname+vehicle_km;
         
     
        RETURN IFNULL(b_name,0);
 END$$

