DROP FUNCTION IF EXISTS `get_loading_off`$$
CREATE FUNCTION `get_loading_off`(v_journeyid VARCHAR(200),v_type VARCHAR(200)) RETURNS decimal(10,0)
    DETERMINISTIC
BEGIN
       
       DECLARE D_QTY DOUBLE;       
       
           IF v_type='LOADING' THEN
          
            SELECT sum(if(offqty>50,offqty/1000,offqty)) INTO D_QTY from journeylog_d WHERE CSALE=1 and  journeyid=v_journeyid GROUP BY journeyid;
                  
           END IF;

           IF v_type='OFFLOADING' THEN
          
            SELECT sum(if(offqty>50,offqty/1000,offqty)) INTO D_QTY from journeylog_d WHERE CSALE=2 and  journeyid=v_journeyid  GROUP BY journeyid;
                  
           END IF;

         RETURN IFNULL(D_QTY,0);
 END$$

