CREATE FUNCTION `get_smallest_qty`(qty DOUBLE,v_pu CHAR(20)) RETURNS double
    DETERMINISTIC
BEGIN
       DECLARE s_qty DOUBLE;

          SELECT IFNULL(factor,1) INTO s_qty FROM pu WHERE code=v_pu LIMIT 1;

          IF (s_qty < 0 or s_qty  IS NULL) THEN SET s_qty=1;

          END IF;

        RETURN s_qty*qty;
 END$$

