CREATE FUNCTION `get_stock_qty`(v_code CHAR(200),v_loc CHAR(200)) RETURNS double
    DETERMINISTIC
BEGIN
       DECLARE s_qty DOUBLE;

          
          select ifnull(sum(if(ts='+',tqty,tqty*-1))/get_smallest_qty(1,if(sunit is null or sunit='',sunit,sunit)),0)  INTO s_qty from stran a,si b where a.code=b.code and a.code=v_code and a.loc=v_loc  group by a.code,a.loc;

          IF (s_qty  IS NULL) THEN SET s_qty=0;

          END IF;

        RETURN s_qty;
 END$$

