DROP FUNCTION IF EXISTS `get_tsN`$$
CREATE FUNCTION `get_tsN`(v_aircraft VARCHAR(200)) RETURNS double
    DETERMINISTIC
BEGIN
       DECLARE bname DOUBLE;
       DECLARE b_name DOUBLE;
       DECLARE D_DATE date;
       DECLARE AIRCRAFT_TSN DOUBLE;      
          
          select ddate INTO D_DATE from aircraft where ainfo=v_aircraft;

          select ifnull(totalflighthours,0) INTO AIRCRAFT_TSN from aircraft where ainfo=v_aircraft;         

          select ifnull(SUM(totalairtime),0) INTO bname from flight_log_post where posted=1 and ldate>=D_DATE and  flightreg=v_aircraft;
          
          SET b_name=bname+AIRCRAFT_TSN;
         
     
        RETURN IFNULL(b_name,0);
 END$$

