DROP FUNCTION IF EXISTS `get_unit_p`$$
CREATE FUNCTION `get_unit_p`(v_code VARCHAR(200),v_pu VARCHAR(200),v_rate double,v_wich_price VARCHAR(200)) RETURNS double
    DETERMINISTIC
BEGIN
       DECLARE bname DOUBLE;
       DECLARE b_name DOUBLE;
	   DECLARE b_names DOUBLE;
	   
       
		IF v_wich_price<>'BASICPRICE' THEN
		SELECT cost/get_smallest_qty(1,sunit)*get_smallest_qty(1,v_pu)*v_rate INTO b_names FROM si where code=v_code limit 1;
       
		ELSE
		SELECT basicprice/get_smallest_qty(1,sunit)*get_smallest_qty(1,v_pu)*v_rate INTO b_names FROM si where code=v_code limit 1;
       
		END IF;
		RETURN IFNULL(b_names,0);
 END$$

