-- ------------------------------------------------------------
DROP FUNCTION IF EXISTS `last_station`$$
CREATE FUNCTION `last_station`(v_vehicle VARCHAR(200)) RETURNS varchar(200) CHARSET latin1
    DETERMINISTIC
BEGIN
       
       DECLARE V_STATION VARCHAR(200);       
              
           SET V_STATION='';
      
           select IFNULL(if(a.endstation='',b.currentbase,a.endstation),'')  INTO V_STATION from  ( select ifnull(if(endstation='',CONCAT('TRANSIT FROM ',startstation),endstation),'') as endstation,vehicle from journeylog a where vehicle=v_vehicle order by journeydate desc limit 1  ) as a,vehicles b where b.vid=a.vehicle ;
                 
           if V_STATION=''  then
               SELECT currentbase  INTO V_STATION from vehicles where vid=v_vehicle limit 1;
           end if;
     
        RETURN IFNULL(V_STATION,'');
 END$$

