DROP PROCEDURE IF EXISTS `do_production_forcast_new`$$
CREATE PROCEDURE `do_production_forcast_new`(IN v_code VARCHAR(200),IN v_descr VARCHAR(100),in v_stdate date,IN v_qty DOUBLE, IN v_price DOUBLE,IN v_total DOUBLE,IN v_pu VARCHAR(200),IN v_tt VARCHAR(10),IN v_glcode VARCHAR(300),IN v_trancode VARCHAR(200),IN v_trandesc VARCHAR(200),IN v_source VARCHAR(200),IN v_loc VARCHAR(200),IN v_ts VARCHAR(10),IN v_serialized int(1),IN v_serial VARCHAR(200),IN V_staff VARCHAR(40),IN V_ubfeet  VARCHAR(40),IN v_bfeetqty1 VARCHAR(40),IN v_bfeetqty2 VARCHAR(40),IN v_bfeetqty_add1 VARCHAR(40),IN v_bfeetqty_add2 VARCHAR(40),IN v_cwna VARCHAR(40),IN v_clna VARCHAR(40))
BEGIN
        
        DECLARE v_nb  VARCHAR(200);
        DECLARE tempqty DOUBLE; 
        DECLARE tmpqty DOUBLE;
        DECLARE iprice DOUBLE;
        DECLARE itc DOUBLE;
        DECLARE itc1 DOUBLE;
        DECLARE v_count INTEGER;
        DECLARE tqty DOUBLE;
        DECLARE uprice DOUBLE;
        SET v_count = 0;
        SET uprice = v_total/get_smallest_qty(v_qty,v_pu);

	SELECT count(1)
	INTO v_count
	FROM pu
	WHERE code = v_pu limit 1;

        	IF v_count < 1 THEN
		call create_pu(v_pu,v_pu);
	END IF;
 
        SET tqty = get_smallest_qty(v_qty,v_pu);
           
	

	IF v_qty <> 0 THEN
		INSERT INTO stran_forecast (code,descr,stdate,qty,pu,price,total,tqty,tt,staff,sdate,glcode,trancode,trandesc,source,sourced,loc,ts,uprice,serial,batchno,ubfeet,bfeetqty1,bfeetqty2,bfeetqty_add1,bfeetqty_add2,cwna,clna)
		VALUES (v_code,v_descr,v_stdate,v_qty,v_pu,v_price,v_total,tqty,v_tt,v_staff,v_stdate,v_glcode,v_trancode,v_trandesc,v_source,v_source,v_loc,v_ts,uprice,v_serial,v_glcode,v_ubfeet,v_bfeetqty1,v_bfeetqty2,v_bfeetqty_add1,v_bfeetqty_add2,v_cwna,v_clna);              
               	                  
	END IF;
                  
	
END$$

