-- ------------------------------------------------------------
DROP PROCEDURE IF EXISTS `do_siserial_sq`$$
CREATE PROCEDURE `do_siserial_sq`(IN v_code VARCHAR(200),IN v_serial VARCHAR(200),IN v_transign VARCHAR(10),IN v_tsn DOUBLE,IN v_csn DOUBLE,IN v_tso DOUBLE,IN v_cso DOUBLE,IN v_stdate DATE,IN v_loc VARCHAR(200),IN v_subloc VARCHAR(200))
BEGIN
	
        DECLARE v_count DOUBLE;

	SELECT count(1)
	INTO v_count
	FROM siserial
	WHERE code = v_code and serialno = v_serial 
	LIMIT 1;
	
        
	
		

	IF  v_transign='+' THEN
		IF v_count > 0 THEN
			
				UPDATE siserial SET tsn=tsn+v_tsn,csn=csn+V_csn,tso=tso+V_tso,cso=cso+V_cso
				WHERE code = v_code AND serialno = v_serial;
			

		ELSE

			INSERT into siserial (code,serialno,pstatus,screate,dcreate,dmodify,smodify,tsn,csn,mdate,tso,cso,location,sublocation,active)
			VALUES(v_code,v_serial,'New',username,now(),username,now(), v_tsn,v_csn,v_stdate,v_tso,v_cso,v_loc,v_subloc,1);
		END IF;   
	ELSE
		IF v_count> 0 THEN
		         

 			UPDATE siserial SET tsn=tsn-v_tsn,csn=csn-V_csn,tso=tso-V_tso,cso=cso-V_cso
				WHERE code = v_code AND serialno = v_serial;
		ELSE
			INSERT into siserial (code,serialno,pstatus,screate,dcreate,dmodify,smodify,tsn,csn,mdate,tso,cso,location,sublocation,active)
			VALUES(v_code,v_serial,'New',username,now(),username,now(), v_tsn,v_csn,v_stdate,v_tso,v_cso,v_loc,v_subloc,1);	
	
		END IF;
	END IF;

				


END$$

-- ------------------------------------------------------------
DROP PROCEDURE IF EXISTS `do_siserial_transactions`$$
CREATE PROCEDURE `do_siserial_transactions`(IN v_code VARCHAR(200),IN v_serial VARCHAR(100),IN v_stdate date,IN v_staff VARCHAR(200),IN v_trancode VARCHAR(200),IN v_trantype VARCHAR(200),IN v_loc VARCHAR(200),IN v_subloc VARCHAR(200),IN v_transign  varchar(10),IN v_tsn DOUBLE,IN v_csn DOUBLE,IN v_tso DOUBLE,IN v_cso DOUBLE)
BEGIN
        
        
        DECLARE v_qty DOUBLE;
       
        SET v_qty = v_tsn + v_csn + v_tso + v_cso;
           
	

	IF v_qty <> 0 THEN
		INSERT INTO siserialtran(code,serialno,mtdate,staff,staffdate,trandcode,trantype,location,sublocation,transign,tsn,csn,tso,cso)
		VALUES (v_code,v_serial,v_stdate,v_staff,now(),v_trancode,v_trantype,v_loc,v_subloc,v_transign,v_tsn,v_csn,v_tso,v_cso);              
               	                  
	END IF;
                  
	
	IF v_qty <> 0 then
               CALL do_siserial_sq(v_code,v_serial,v_transign,v_tsn,v_csn,v_tso,v_cso,v_stdate,v_loc,v_subloc) ; 	
	END IF;

	

END$$

-- ------------------------------------------------------------
DROP PROCEDURE IF EXISTS `do_stock_sq`$$
CREATE PROCEDURE `do_stock_sq`(IN v_code VARCHAR(200),IN v_qty DOUBLE, IN v_price DOUBLE,IN v_total DOUBLE,IN v_pu VARCHAR(200),IN v_tt VARCHAR(10),IN v_ts VARCHAR(10),IN v_loc VARCHAR(200),IN v_tqty DOUBLE)
BEGIN
	DECLARE v_quantity DOUBLE;
	DECLARE v_totalcost DOUBLE;
	DECLARE v_tq DOUBLE;
        DECLARE v_tqc DOUBLE;
	DECLARE v_w DOUBLE;
	DECLARE v_count	INTEGER;
	DECLARE username VARCHAR(200);
	DECLARE v_wavgc DOUBLE;

	SELECT count(1)
	INTO v_count
	FROM sq
	WHERE code = v_code and loc=v_loc LIMIT 1;
	
        set v_tqc = get_smallest_qty(v_qty,v_pu);
set v_wavgc=v_total/v_tqc;
	
		SELECT 
		quantity,
		totalcost,
                                   IFNULL(totalcost/quantity,wavgc) as tq,
		wavgc as w
		INTO
		v_quantity,
 		v_totalcost,
		v_tq,
		v_w
                                   FROM sq WHERE code = v_code AND loc = v_loc limit 1;

	IF  v_ts='+' THEN
		IF v_count > 0 THEN
			IF V_wavgc <> 0 THEN
				UPDATE  sq SET quantity=quantity+v_tqc,wavgc=v_wavgc
				WHERE code = v_code  AND loc = v_loc;
			ELSE
				UPDATE sq SET quantity=quantity+v_tqc,wavgc=v_wavgc
				WHERE code = v_code AND loc = v_loc;
			END IF;

		ELSE

			INSERT INTO sq (code,loc,totalcost,quantity,qty,lastupdated,updatedby,datecreated,createdby,wavgc)
			VALUES(v_code,v_loc,v_total,v_tqc,v_qty,current_date(),username,current_date(),username ,v_wavgc);
		END IF;   
	ELSE
		IF v_count> 0 THEN
		         

 			UPDATE sq SET totalcost=totalcost-v_total,
			quantity=quantity-v_tqc 
			WHERE code = v_code and loc = v_loc;
		ELSE
			INSERT INTO sq (code,loc,totalcost,quantity,qty,lastupdated,updatedby,datecreated,createdby,wavgc)
			VALUES(v_code,v_loc,v_total,v_tqc*-1,v_tqc*-1,current_date(),username,current_date(),username ,v_wavgc);	
	
		END IF;
	END IF;

				


END$$

-- ------------------------------------------------------------
DROP PROCEDURE IF EXISTS `do_stock_sq_new`$$
CREATE PROCEDURE `do_stock_sq_new`(IN v_code VARCHAR(200),IN v_qty DOUBLE, IN v_price DOUBLE,IN v_total DOUBLE,IN v_pu VARCHAR(200),IN v_tt VARCHAR(10),IN v_ts VARCHAR(10),IN v_loc VARCHAR(200),IN v_tqty DOUBLE)
BEGIN
	DECLARE v_quantity DOUBLE;
	DECLARE v_totalcost DOUBLE;
	DECLARE v_tq DOUBLE;
        DECLARE v_tqc DOUBLE;
	DECLARE v_w DOUBLE;
	DECLARE v_count	INTEGER;
	DECLARE username VARCHAR(200);
	DECLARE v_wavgc DOUBLE;

	SELECT count(1)
	INTO v_count
	FROM sq
	WHERE code = v_code and loc=v_loc LIMIT 1;
	
        set v_tqc = get_smallest_qty(v_qty,v_pu);
set v_wavgc=v_total/v_tqc;
	
		SELECT 
		quantity,
		totalcost,
                                   IFNULL(totalcost/quantity,wavgc) as tq,
		wavgc as w
		INTO
		v_quantity,
 		v_totalcost,
		v_tq,
		v_w
                                   FROM sq WHERE code = v_code AND loc = v_loc limit 1;

	IF  v_ts='+' THEN
		IF v_count > 0 THEN
			IF V_wavgc <> 0 THEN
				UPDATE  sq SET quantity=quantity+v_tqc,wavgc=((wavgc*quantity)+(v_wavgc*v_tqc))/(quantity+v_tqc)
				WHERE code = v_code  AND loc = v_loc;
			ELSE
				UPDATE sq SET quantity=quantity+v_tqc,wavgc=((wavgc*quantity)+(v_wavgc*v_tqc))/(quantity+v_tqc)
				WHERE code = v_code AND loc = v_loc;
			END IF;

		ELSE

			INSERT INTO sq (code,loc,totalcost,quantity,qty,lastupdated,updatedby,datecreated,createdby,wavgc)
			VALUES(v_code,v_loc,v_total,v_tqc,v_qty,current_date(),username,current_date(),username ,v_wavgc);
		END IF;   
	ELSE
		IF v_count> 0 THEN
		         

 			UPDATE sq SET totalcost=totalcost-v_total,
			quantity=quantity-v_tqc 
			WHERE code = v_code and loc = v_loc;
		ELSE
			INSERT INTO sq (code,loc,totalcost,quantity,qty,lastupdated,updatedby,datecreated,createdby,wavgc)
			VALUES(v_code,v_loc,v_total,v_tqc*-1,v_tqc*-1,current_date(),username,current_date(),username ,v_wavgc);	
	
		END IF;
	END IF;

				


END$$

