DROP PROCEDURE IF EXISTS `do_stock_transactions`$$
CREATE PROCEDURE `do_stock_transactions`(IN v_code VARCHAR(200),IN v_descr VARCHAR(100),in v_stdate date,IN v_qty DOUBLE, IN v_price DOUBLE,IN v_total DOUBLE,IN v_pu VARCHAR(200),IN v_tt VARCHAR(10),IN v_glcode VARCHAR(200),IN v_trancode VARCHAR(200),IN v_trandesc VARCHAR(200),IN v_source VARCHAR(200),IN v_loc VARCHAR(200),IN v_ts VARCHAR(10),IN v_serialized int(1),IN v_serial VARCHAR(200),IN V_staff VARCHAR(40))
BEGIN
        
        DECLARE v_nb  VARCHAR(200);
        DECLARE tempqty DOUBLE; 
        DECLARE tmpqty DOUBLE;
        DECLARE iprice DOUBLE;
        DECLARE itc DOUBLE;
        DECLARE itc1 DOUBLE;
        DECLARE v_count INTEGER;
        DECLARE tqty DOUBLE;
        DECLARE uprice DOUBLE;
        SET v_count = 0;
        SET uprice = v_total/get_smallest_qty(v_qty,v_pu);

	SELECT count(1)
	INTO v_count
	FROM pu
	WHERE code = v_pu limit 1;

        	IF v_count < 1 THEN
		call create_pu(v_pu,v_pu);
	END IF;
 
        SET tqty = get_smallest_qty(v_qty,v_pu);
           
	

	IF v_qty <> 0 THEN
		INSERT INTO stran (code,descr,stdate,qty,pu,price,total,tqty,tt,staff,sdate,glcode,trancode,trandesc,source,sourced,loc,ts,uprice,serial,batchno)
		VALUES (v_code,v_descr,v_stdate,v_qty,v_pu,v_price,v_total,tqty,v_tt,v_staff,now(),v_glcode,v_trancode,v_trandesc,v_source,v_source,v_loc,v_ts,uprice,v_serial,v_glcode);              
               	                  
	END IF;
                  
	
	IF v_qty <> 0 then
                		CALL do_stock_sq(v_code,v_qty,v_price,v_total,v_pu,v_tt,v_ts,v_loc,v_qty) ; 	
	END IF;

	

END$$

