DROP PROCEDURE IF EXISTS `do_stock_transactions_new`$$
CREATE PROCEDURE `do_stock_transactions_new`(IN v_code VARCHAR(200),IN v_descr VARCHAR(100),in v_stdate date,IN v_qty DOUBLE, IN v_price DOUBLE,IN v_total DOUBLE,IN v_pu VARCHAR(200),IN v_tt VARCHAR(10),IN v_glcode VARCHAR(200),IN v_trancode VARCHAR(200),IN v_trandesc VARCHAR(200),IN v_source VARCHAR(200),IN v_loc VARCHAR(200),IN v_ts VARCHAR(10),IN v_serialized int(1),IN v_serial VARCHAR(200),IN V_staff VARCHAR(40),IN v_unit DOUBLE,IN v_unittotal DOUBLE,IN v_prunits2 VARCHAR(40),IN v_unitstd DOUBLE)
